MERGE t_prodordhdr_copy1 AS target USING (VALUES
(#{row.BP}, #{row.F_ID}, #{row.F_DOCDATE}, /* ... */)
) AS src(BP, F_ID, F_DOCDATE /* ... */) ON target.BP = src.BP AND target.F_ID = src.F_ID WHEN MATCHED THEN UPDATE SET F_DOCDATE = src.F_DOCDATE /* ... */ WHEN NOT MATCHED THEN INSERT (BP, F_ID, F_DOCDATE /* ... */) VALUES (src.BP, src.F_ID, src.F_DOCDATE /* ... */);

mapper.delete:
DELETE FROM t_prodordhdr_copy1
WHERE BP = #{BP} AND F_ID IN
#{id}
